<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Factories\HasFactory;
class Employee extends Model{use HasFactory;protected $fillable=['employee_code','name','normalized_name','iqama_no','passport_no','designation_id','company_id','current_project_id','shift','accommodation','doj','phone','hourly_rate','monthly_salary','status','remarks','source_sheet'];protected function casts():array{return ['doj'=>'date'];}protected static function booted():void{static::saving(fn($e)=>$e->normalized_name=self::normalizeName($e->name));}public static function normalizeName(?string $n):string{return trim(preg_replace('/\s+/',' ',mb_strtoupper((string)$n)));}public function company(){return $this->belongsTo(Company::class);}public function designation(){return $this->belongsTo(Designation::class);}public function currentProject(){return $this->belongsTo(Project::class,'current_project_id');}public function attendanceRecords(){return $this->hasMany(AttendanceRecord::class);}public function advancePayments(){return $this->hasMany(AdvancePayment::class);}public function extraDuties(){return $this->hasMany(ExtraDuty::class);}public function payslips(){return $this->hasMany(Payslip::class);}}
